bool run(lua_State* state, const char* script) {
    if (luaL_dostring(state, script) == LUA_OK) return true;
    std::fprintf(stderr, "Lua assertion failed: %s\n", lua_tostring(state, -1));
    lua_pop(state, 1);
    return false;
}

bool changed(lua_State* state, const char* path) {
    lua_getglobal(state, "fgcnote_native_io");
    lua_getfield(state, -1, "changed");
    lua_pushstring(state, path);
    if (lua_pcall(state, 1, 2, 0) != LUA_OK) {
        std::fprintf(stderr, "changed() failed: %s\n", lua_tostring(state, -1));
        lua_settop(state, 0);
        return false;
    }
    const auto dirty = lua_toboolean(state, -2) != 0;
    lua_settop(state, 0);
    return dirty;
}

lua_State* new_state() {
    auto* state = luaL_newstate();
    if (!state) return nullptr;
    luaL_openlibs(state);
    g_created(state);
    return state;
}

