int main(int argc, char** argv) {
    const auto stock_api = argc > 1 && std::strcmp(argv[1], "--stock") == 0;
    g_extension_enabled = !stock_api;
    const auto plugin = LoadLibraryW(L"reframework\\plugins\\fgcnote_io.dll");
    if (!plugin) {
        std::fprintf(stderr, "LoadLibraryW failed: %lu\n", GetLastError());
        return 1;
