        GetProcAddress(plugin, "reframework_plugin_initialize"));
    const auto required_version = reinterpret_cast<REFPluginRequiredVersionFn>(
        GetProcAddress(plugin, "reframework_plugin_required_version"));
    if (!initialize || !required_version) {
        std::fprintf(stderr, "plugin exports are incomplete\n");
        return 1;
    }

    REFrameworkPluginVersion requirement{};
    required_version(&requirement);
    if (requirement.major != 1 || requirement.minor > 15) {
        std::fprintf(stderr, "unexpected plugin requirement %d.%d.%d\n",
            requirement.major, requirement.minor, requirement.patch);
        return 1;
    }

    g_functions.on_lua_state_created = register_created;
    g_functions.on_lua_state_destroyed = register_destroyed;
    g_functions.log_error = log_error;
    g_functions.log_warn = log_warn;
    g_functions.log_info = log_info;

    REFrameworkPluginVersion framework_version{1, 15, 0, "SF6"};
    REFrameworkPluginInitializeParam parameter{};
    parameter.version = &framework_version;
    parameter.functions = &g_functions;
    if (!initialize(&parameter) || !g_created || !g_destroyed) {
